        raise ValueError('expected two nonzero colors')
    # The large enclosing color forms a rectangular frame around the smaller
    # inner-color rectangle. The frame thickness determines the outward growth.
    boxes = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        boxes[color] = (min(r for r,c in cells), max(r for r,c in cells),
                        min(c for r,c in cells), max(c for r,c in cells), len(cells))
    outer = max(colors, key=lambda x: boxes[x][4])
    inner = next(x for x in colors if x != outer)
    ro0, ro1, co0, co1, _ = boxes[outer]
    ri0, ri1, ci0, ci1, _ = boxes[inner]
    thickness = min(ri0-ro0, ro1-ri1, ci0-co0, co1-ci1)
    if thickness <= 0:
        raise ValueError('inner object is not enclosed')
    out = [row[:] for row in grid]
    r0, r1 = max(0, ro0-thickness), min(h-1, ro1+thickness)
    c0, c1 = max(0, co0-thickness), min(w-1, co1+thickness)
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            if out[r][c] == 0:
                out[r][c] = inner
    return out

